#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
INSTALADOR - Examen "17 de Junio" (pagina del Sindicato)
=========================================================
Crea un examen interactivo nuevo en sindicato-sesion1:
  src/data/examen-17-junio.js              (10 reactivos | clave 1706 | 90s | orden fijo)
  src/app/examen/17-junio/page.js          (misma plantilla que tus otros examenes)
Y agrega 1 tarjeta al home (array EXAMENES) que enlaza al examen.

10 reactivos de Caracteristicas/Criterios, Fines, LGDNNA, Objetivos NEM y
Programa Analitico. NO repite los del examen Nivel 2 y 3 ya publicado.

Seguro: respaldo automatico, idempotente (se puede correr de nuevo).
Ejecutar desde la raiz del proyecto:
    cd ~/Desktop/sindicato-sesion1
    python3 instalar_examen_17junio.py
"""
import os, sys, base64, json, shutil
from datetime import datetime

PAYLOAD_B64 = ""

ROOT = os.getcwd()
TS = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP_DIR = os.path.join(ROOT, "_backups_examen_17junio_" + TS)

DATA_OUT = os.path.join(ROOT, "src", "data", "examen-17-junio.js")
PAGE_OUT = os.path.join(ROOT, "src", "app", "examen", "17-junio", "page.js")
HOME = os.path.join(ROOT, "src", "app", "page.js")
ANCHOR = "const EXAMENES = ["
GUARD = 'id: "17-junio"'

def die(m):
    print("\n[ERROR] " + m); sys.exit(1)

def backup(p):
    if os.path.isfile(p):
        rel = os.path.relpath(p, ROOT)
        dst = os.path.join(BACKUP_DIR, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(p, dst); return True
    return False

def write_file(p, content):
    existed = backup(p)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w", encoding="utf-8") as f:
        f.write(content)
    rel = os.path.relpath(p, ROOT)
    print(("   [~] actualizado " if existed else "   [+] creado     ") + rel)

def patch_home(card):
    if not os.path.isfile(HOME):
        print("   [!] No encontre src/app/page.js; OMITO la tarjeta (el examen queda en /examen/17-junio)."); return
    with open(HOME, "r", encoding="utf-8") as f:
        content = f.read()
    if GUARD in content:
        print("   [=] El home ya tiene la tarjeta del 17 de junio (sin cambios)."); return
    if ANCHOR not in content:
        print("   [!] No encontre 'const EXAMENES = ['; OMITO la tarjeta. El examen ya queda en /examen/17-junio."); return
    backup(HOME)
    content = content.replace(ANCHOR, ANCHOR + card, 1)
    with open(HOME, "w", encoding="utf-8") as f:
        f.write(content)
    print("   [~] src/app/page.js (tarjeta agregada al inicio de EXAMENES)")

def main():
    print("=" * 60)
    print("  EXAMEN 17 DE JUNIO - Sindicato (SNTE Seccion 21)")
    print("  10 reactivos | clave 1706 | 90s | orden fijo")
    print("=" * 60)

    if not os.path.isdir(os.path.join(ROOT, "src", "data")) or not os.path.isdir(os.path.join(ROOT, "src", "app")):
        die("No parece la raiz de sindicato-sesion1.\n"
            "   Entra a la carpeta:  cd ~/Desktop/sindicato-sesion1\n"
            "   (debe existir src/data/ y src/app/)")

    data = json.loads(base64.b64decode(PAYLOAD_B64).decode())
    data_js = base64.b64decode(data["data_b64"]).decode()
    page_js = base64.b64decode(data["page_b64"]).decode()
    card = base64.b64decode(data["card_b64"]).decode()

    print("\nProyecto: " + ROOT)
    print("Backups : " + os.path.relpath(BACKUP_DIR, ROOT) + "/  (solo si algo existia)\n")
    print("Escribiendo archivos:")
    write_file(DATA_OUT, data_js)
    write_file(PAGE_OUT, page_js)
    print("\nEnlazando en el home:")
    patch_home(card)

    print("\n" + "=" * 60)
    print("LISTO. Examen disponible en:  /examen/17-junio   (clave 1706)")
    print("\nVerifica y publica:")
    print("   npm run build")
    print("   git add src/data/examen-17-junio.js src/app/examen/17-junio/page.js src/app/page.js")
    print('   git commit -m "Examen 17 de junio (10 reactivos, clave 1706)"')
    print("   git push")
    print("=" * 60)

if __name__ == "__main__":
    main()
